class Ats{static Map<String,dynamic> run(String text,String job){final t=text.toLowerCase();final checks={'Contact info':t.contains('@')||t.contains('phone')||t.contains('linkedin'),'Summary':t.contains('summary')||t.contains('profile'),'Experience':t.contains('experience')||t.contains('employment'),'Education':t.contains('education'),'Skills':t.contains('skills'),'Bullets':text.split('\n').any((l)=>l.trim().startsWith('-')||l.trim().startsWith('•')),'Length':text.split(RegExp(r'\s+')).length>=250&&text.split(RegExp(r'\s+')).length<=1200};final jw=RegExp(r'\b[a-zA-Z]{4,}\b').allMatches(job.toLowerCase()).map((m)=>m.group(0)!).toSet();final rw=RegExp(r'\b[a-zA-Z]{4,}\b').allMatches(t).map((m)=>m.group(0)!).toSet();return {'checks':checks,'score':(checks.values.where((x)=>x).length/checks.length*100).round(),'matches':jw.intersection(rw).toList(),'gaps':jw.difference(rw).take(50).toList()};}}
